; Exception-only ISR stubs (vectors 0-31). This kernel is single-tasking and
; polling-only - interrupts are never enabled (no `sti`, no PIC remap, no
; IRQ handlers) - so the only things that can land here are synchronous CPU
; exceptions. There is no recovery path: each stub reports the vector/error
; code to the C handler and then halts forever, so no iret/register
; restore is needed.

; Each stub below is hand-expanded rather than generated by a macro - AS has
; no macro preprocessor, since this was the only place in the codebase that
; needed one. Vectors 8, 10-14 and 17 push only the vector number, since the
; CPU already pushes an error code for those exceptions; every other vector
; pushes a dummy 0 error code first, so isr_common always sees the same
; [vector][error_code] stack layout regardless of which vector fired.

BITS 32
section .text

extern isr_handler

global isr_stub_0
isr_stub_0:
    push dword 0
    push dword 0
    jmp isr_common

global isr_stub_1
isr_stub_1:
    push dword 0
    push dword 1
    jmp isr_common

